scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_173'] || []

control 'CKV_AWS_173' do
  title 'Check encryption settings for Lambda environmental variable'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_lambda_function resources that actually exist, enumerated
    through the declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    Environment variables hold configuration that is frequently credentials;
    with the default key they are encrypted with a key the account cannot
    rotate or revoke.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: Check encryption settings for Lambda environmental
    variable
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_lambda_function:

      resource "aws_lambda_function" "example" {
        kms_key_arn = aws_kms_key.lambda.arn
      }

    Out of band — aws_lambda_function:

      aws lambda update-function-configuration --function-name <name> --kms-key-arn <key-arn>
  FIX

  tag checkov_id:            'CKV_AWS_173'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_lambda_function]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/lambda_function'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'reviewed'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_lambda_function', regions: scan_regions)

  # A field the API did not return is nil, and nil is not a failing value: the
  # asset does not express this setting, so it is out of scope for this check
  # rather than in breach of it.
  in_scope = assets.assets(exempt: exempt).reject { |a| a[:kms_key_arn].nil? }

  applicable = !in_scope.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_lambda_function in scope expressing this setting') { applicable }

  in_scope.each do |asset|
    describe "aws_lambda_function #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:kms_key_arn] }
      it { should_not be_empty }
    end
  end
end
